// NAMA multimovies provider v1.3.1, generated by build.py; edit src/ instead.

// ---- common/http.js ----
// Shared HTTP helpers. Runtime code is plain ES2020 with Promise chains so it
// runs inside Nuvio's Hermes engine without transpiling.

var NAMA_UA =
  "Mozilla/5.0 (Linux; Android 13; Pixel 7) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Mobile Safari/537.36";

function namaFetchText(url, opts) {
  opts = opts || {};
  var headers = Object.assign({ "User-Agent": NAMA_UA }, opts.headers || {});
  return fetch(url, { method: opts.method || "GET", headers: headers, body: opts.body }).then(function (res) {
    if (!res.ok) throw new Error("HTTP " + res.status + " " + url);
    return res.text();
  });
}

function namaFetchJson(url, opts) {
  return namaFetchText(url, opts).then(function (t) {
    return JSON.parse(t);
  });
}

function namaOrigin(url) {
  var m = /^(https?:\/\/[^\/]+)/i.exec(url);
  return m ? m[1] : "";
}

function namaHost(url) {
  return namaOrigin(url).replace(/^https?:\/\//i, "");
}

// Resolve a playlist URI against the playlist it came from.
function namaResolveUrl(uri, baseUrl) {
  if (/^https?:\/\//i.test(uri)) return uri;
  if (uri.indexOf("//") === 0) return "https:" + uri;
  if (uri.charAt(0) === "/") return namaOrigin(baseUrl) + uri;
  var dir = baseUrl.split("?")[0].replace(/[^\/]*$/, "");
  return dir + uri;
}

var NAMA_B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

// UTF-8 safe base64 encoder (btoa is not guaranteed in Hermes).
function namaBase64(str) {
  var bytes = [];
  for (var i = 0; i < str.length; i++) {
    var c = str.charCodeAt(i);
    if (c < 0x80) bytes.push(c);
    else if (c < 0x800) bytes.push(0xc0 | (c >> 6), 0x80 | (c & 63));
    else bytes.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
  }
  var out = "";
  for (var j = 0; j < bytes.length; j += 3) {
    var n = (bytes[j] << 16) | ((bytes[j + 1] || 0) << 8) | (bytes[j + 2] || 0);
    out += NAMA_B64[(n >> 18) & 63] + NAMA_B64[(n >> 12) & 63];
    out += j + 1 < bytes.length ? NAMA_B64[(n >> 6) & 63] : "=";
    out += j + 2 < bytes.length ? NAMA_B64[n & 63] : "=";
  }
  return out;
}

// ---- common/tmdb.js ----
// TMDB metadata lookup. Get a free v3 API key at https://www.themoviedb.org/settings/api
// and put it here before building.
var TMDB_API_KEY = "439c478a771f35c05022f9feabcca01c";
// api.themoviedb.org is blocked on many Indian networks; api.tmdb.org is the same API.
var TMDB_BASES = ["https://api.tmdb.org/3", "https://api.themoviedb.org/3"];

function tmdbGet(path) {
  var sep = path.indexOf("?") >= 0 ? "&" : "?";
  var q = path + sep + "api_key=" + TMDB_API_KEY;
  return namaFetchJson(TMDB_BASES[0] + q).catch(function () {
    return namaFetchJson(TMDB_BASES[1] + q);
  });
}

// Resolves "tt..." IMDb ids to a TMDB id.
function tmdbResolveId(id, mediaType) {
  id = String(id);
  if (id.indexOf("tt") !== 0) return Promise.resolve(id);
  return tmdbGet("/find/" + id + "?external_source=imdb_id").then(function (r) {
    var list = mediaType === "movie" ? r.movie_results : r.tv_results;
    if (!list || !list.length) throw new Error("TMDB: no match for " + id);
    return String(list[0].id);
  });
}

// Returns { type, tmdbId, originalLanguage, title, original, year, poster, season, episode, absEpisode, episodeName, altTitles }.
function tmdbMeta(tmdbId, mediaType, season, episode) {
  var isMovie = mediaType === "movie";
  return tmdbResolveId(tmdbId, mediaType)
    .then(function (id) {
      return tmdbGet((isMovie ? "/movie/" : "/tv/") + id);
    })
    .then(function (d) {
      var meta = {
        type: isMovie ? "movie" : "tv",
        tmdbId: String(d.id),
        originalLanguage: d.original_language || "",
        title: isMovie ? d.title : d.name,
        original: isMovie ? d.original_title : d.original_name,
        year: ((isMovie ? d.release_date : d.first_air_date) || "").slice(0, 4),
        poster: d.poster_path || "",
        season: season,
        episode: episode,
        absEpisode: episode,
        episodeName: "",
        altTitles: [],
      };
      return tmdbAltTitles(d.id, isMovie)
        .then(function (alts) {
          meta.altTitles = alts;
        })
        .then(function () {
          return tmdbEpisodeMeta(d, meta);
        });
    });
}

// Regional titles help where the site uses a local name (e.g. "Shin-Chan" for "Crayon Shin-chan").
var TMDB_ALT_COUNTRIES = ["IN", "US", "GB"];

function tmdbAltTitles(id, isMovie) {
  return tmdbGet((isMovie ? "/movie/" : "/tv/") + id + "/alternative_titles")
    .then(function (r) {
      var list = (isMovie ? r.titles : r.results) || [];
      return list
        .filter(function (x) {
          return /^[\x20-\x7e]+$/.test(x.title || "");
        })
        .sort(function (a, b) {
          var ia = TMDB_ALT_COUNTRIES.indexOf(a.iso_3166_1);
          var ib = TMDB_ALT_COUNTRIES.indexOf(b.iso_3166_1);
          return (ia < 0 ? 99 : ia) - (ib < 0 ? 99 : ib);
        })
        .map(function (x) {
          return x.title;
        });
    })
    .catch(function () {
      return [];
    });
}

// Adds absolute episode number and episode name for tv.
function tmdbEpisodeMeta(d, meta) {
  if (meta.type === "movie") return meta;
  var before = 0;
  (d.seasons || []).forEach(function (s) {
    if (s.season_number > 0 && s.season_number < meta.season) before += s.episode_count || 0;
  });
  meta.absEpisode = before + meta.episode;
  return tmdbGet("/tv/" + d.id + "/season/" + meta.season + "/episode/" + meta.episode)
    .then(function (ep) {
      meta.episodeName = ep.name || "";
      return meta;
    })
    .catch(function () {
      return meta;
    });
}

// ---- common/format.js ----
// Stream formatter: how each stream card reads in Nuvio.
//
// Nuvio shows `name` in bold and grey text built from `quality • size • language`;
// `title` is only used when `name` is missing. Everything grey goes in `size`.
//
// 1080p | Multi Audio                 (single language: "1080p | Hindi")
// 🎬 Naruto | S01 E05                 (movies: title only)
// 🎧 HIN • TAM • TEL • ENG • JPN      (multi-audio only)
// 📺 HLS • AVC • AAC 2.0
// 🌐 AnimeSalt | ravok.buzz
//
// The wording is chosen so Nuvio badge packs (regexes over name + description) can match:
// "1080p", "Multi Audio", full language names, ISO 639-2 codes (hin, eng, jpn), codecs, channels.

var NAMA_LANGS = {
  hin: "HI", hi: "HI", hindi: "HI",
  tam: "TA", ta: "TA", tamil: "TA",
  tel: "TE", te: "TE", telugu: "TE",
  mal: "ML", ml: "ML", malayalam: "ML",
  ben: "BN", bn: "BN", bengali: "BN", bangla: "BN",
  kan: "KN", kn: "KN", kannada: "KN",
  mar: "MR", mr: "MR", marathi: "MR",
  eng: "EN", en: "EN", english: "EN",
  jpn: "JA", ja: "JA", jap: "JA", japanese: "JA",
  kor: "KO", ko: "KO", korean: "KO",
  zho: "ZH", chi: "ZH", zh: "ZH", chinese: "ZH",
  spa: "ES", es: "ES", spanish: "ES",
  fra: "FR", fre: "FR", fr: "FR", french: "FR",
  deu: "DE", ger: "DE", de: "DE", german: "DE",
  ita: "IT", it: "IT", italian: "IT",
  por: "PT", pt: "PT", portuguese: "PT",
  rus: "RU", ru: "RU", russian: "RU",
  ara: "AR", ar: "AR", arabic: "AR",
  ind: "ID", id: "ID", indonesian: "ID",
  tha: "TH", th: "TH", thai: "TH",
  vie: "VI", vi: "VI", vietnamese: "VI",
};
// Language preference, used for sorting and for the audio line.
var NAMA_LANG_ORDER = ["HI", "TA", "TE", "ML", "BN", "KN", "MR", "EN", "JA", "KO", "ZH"];
// Display forms: ISO 639-2 short codes and full names (both are what badge packs look for).
var NAMA_LANG_INFO = {
  HI: ["HIN", "Hindi"], TA: ["TAM", "Tamil"], TE: ["TEL", "Telugu"], ML: ["MAL", "Malayalam"],
  BN: ["BEN", "Bengali"], KN: ["KAN", "Kannada"], MR: ["MAR", "Marathi"], EN: ["ENG", "English"],
  JA: ["JPN", "Japanese"], KO: ["KOR", "Korean"], ZH: ["CHI", "Chinese"],
  ES: ["SPA", "Spanish"], FR: ["FRE", "French"], DE: ["GER", "German"], IT: ["ITA", "Italian"],
  PT: ["POR", "Portuguese"], RU: ["RUS", "Russian"], AR: ["ARA", "Arabic"], ID: ["IND", "Indonesian"],
  TH: ["THA", "Thai"], VI: ["VIE", "Vietnamese"],
};

// Stream sort keys, most important first; reorder (or drop) to taste and rebuild.
//   "resolution": 1080p before 720p
//   "multi":      more audio languages first (multi-audio before single-language)
//   "language":   streams with a language earlier in NAMA_LANG_ORDER first (Hindi, then Tamil, ...)
var NAMA_SORT = ["resolution", "multi", "language"];

function namaLangCode(audio) {
  // Names can be numbered ("8. Hindi") or carry extras ("Hindi (Original)").
  var name = String(audio.name || "").replace(/^\s*\d+[.)]?\s*/, "").trim();
  var keys = [audio.lang, name, name.split(/[\s(\[-]/)[0]];
  for (var i = 0; i < keys.length; i++) {
    var k = String(keys[i] || "").toLowerCase().trim();
    if (NAMA_LANGS[k]) return NAMA_LANGS[k];
  }
  // Unmapped ISO code ("pol", "ukr") is shown as-is; otherwise the name's first letters.
  if (/^[a-z]{2,3}$/i.test(audio.lang || "") && !/^(und|mul|unk)$/i.test(audio.lang)) return audio.lang.toUpperCase();
  var letters = name.replace(/[^a-z]/gi, "");
  return letters ? letters.slice(0, 3).toUpperCase() : "UND";
}

function namaLangs(audios) {
  var codes = [];
  audios.forEach(function (a) {
    var c = namaLangCode(a);
    if (codes.indexOf(c) < 0) codes.push(c);
  });
  return codes.sort(function (a, b) {
    var ia = NAMA_LANG_ORDER.indexOf(a);
    var ib = NAMA_LANG_ORDER.indexOf(b);
    return (ia < 0 ? 99 : ia) - (ib < 0 ? 99 : ib);
  });
}

function namaLangShort(code) {
  return (NAMA_LANG_INFO[code] || [code])[0];
}

function namaLangFull(code, audio) {
  if (NAMA_LANG_INFO[code]) return NAMA_LANG_INFO[code][1];
  return (audio && audio.name) || code;
}

// Longest title shown on the card before it is cut with "…".
var NAMA_TITLE_MAX = 32;

function namaPad2(n) {
  var s = String(parseInt(n, 10) || 0);
  return s.length < 2 ? "0" + s : s;
}

// "Naruto | S01 E05"; movies just the title. Plain ASCII digits.
function namaTitleLine(meta) {
  var t = String(meta.title || "").replace(/\s+/g, " ").trim();
  if (t.length > NAMA_TITLE_MAX) t = t.slice(0, NAMA_TITLE_MAX - 1).replace(/[\s:,.\-]+$/, "") + "…";
  if (meta.type === "movie") return t;
  return t + " | S" + namaPad2(meta.season) + " E" + namaPad2(meta.episode);
}

var NAMA_VIDEO_CODECS = [[/^avc/, "AVC"], [/^(hvc|hev)/, "HEVC"], [/^av01/, "AV1"], [/^vp0?9/, "VP9"]];
var NAMA_AUDIO_CODECS = [[/^mp4a\.40\.(2|5|29)$/, "AAC"], [/^mp4a/, "AAC"], [/^ac-3/, "DD"], [/^ec-3/, "DD+"], [/^opus/, "OPUS"], [/^flac/, "FLAC"]];
var NAMA_CHANNELS = { 1: "1.0", 2: "2.0", 6: "5.1", 8: "7.1" };

function namaCodec(list, codecs) {
  for (var i = 0; i < codecs.length; i++) {
    for (var j = 0; j < list.length; j++) {
      if (list[j][0].test(codecs[i])) return list[j][1];
    }
  }
  return "";
}

// Technical line from the variant's #EXT-X-STREAM-INF and the audio renditions: "HLS • AVC • AAC 2.0".
function namaTech(inf, audios, format) {
  var codecs = String((/CODECS="([^"]*)"/.exec(inf || "") || [])[1] || "")
    .toLowerCase()
    .split(",")
    .map(function (c) {
      return c.trim();
    });
  var video = namaCodec(NAMA_VIDEO_CODECS, codecs);
  var audio = namaCodec(NAMA_AUDIO_CODECS, codecs);
  var ch = "";
  for (var i = 0; i < audios.length && !ch; i++) {
    var n = (/CHANNELS="(\d+)/.exec(audios[i].line || "") || [])[1];
    if (n) ch = NAMA_CHANNELS[n] || n + "ch";
  }
  var parts = [format || "HLS"];
  if (video) parts.push(video);
  if (audio || ch) parts.push([audio, ch].filter(Boolean).join(" "));
  return parts.join(" • ");
}

// heights: resolutions this stream carries (one for per-resolution streams).
// inf: the #EXT-X-STREAM-INF line of the video variant, for codecs (optional).
function namaFormatStream(ctx, url, heights, inf) {
  var langs = namaLangs(ctx.audios);
  var res = heights.filter(function (h) {
    return h > 0;
  });
  var quality = res.length ? res[0] + "p" : "Auto";
  var multi = langs.length > 1;
  var langLabel = multi ? "Multi Audio" : langs.length ? namaLangFull(langs[0], ctx.audios[0]) : "Unknown";
  var name = quality + " | " + langLabel;
  var lines = [];
  if (ctx.meta && ctx.meta.title) lines.push("🎬 " + namaTitleLine(ctx.meta));
  if (multi) lines.push("🎧 " + langs.map(namaLangShort).join(" • "));
  lines.push("📺 " + namaTech(inf, ctx.audios, ctx.format));
  lines.push("🌐 " + ctx.site.name + " | " + (ctx.server || ctx.host));
  var size = lines.join("\n");
  return {
    name: name,
    title: name + "\n" + size,
    url: url,
    size: size,
    provider: ctx.site.name,
    type: ctx.format === "MP4" ? "mp4" : "hls",
    headers: ctx.headers,
    behaviorHints: { notWebReady: true },
    _langCount: langs.length,
    _langs: langs,
    _height: heights[0] || 0,
  };
}

// The first language in NAMA_LANG_ORDER that one stream has and the other lacks decides.
function namaCompareLangs(a, b) {
  for (var i = 0; i < NAMA_LANG_ORDER.length; i++) {
    var ha = a.indexOf(NAMA_LANG_ORDER[i]) >= 0;
    var hb = b.indexOf(NAMA_LANG_ORDER[i]) >= 0;
    if (ha !== hb) return ha ? -1 : 1;
  }
  return 0;
}

var NAMA_SORT_KEYS = {
  resolution: function (a, b) {
    return b._height - a._height;
  },
  multi: function (a, b) {
    return b._langCount - a._langCount;
  },
  language: function (a, b) {
    return namaCompareLangs(a._langs, b._langs);
  },
};

// Sorts by NAMA_SORT; ties keep provider order.
function namaSortStreams(streams) {
  var keys = NAMA_SORT.map(function (k) {
    return NAMA_SORT_KEYS[k];
  }).filter(Boolean);
  return streams
    .map(function (s, i) {
      s._index = i;
      return s;
    })
    .sort(function (a, b) {
      for (var i = 0; i < keys.length; i++) {
        var d = keys[i](a, b);
        if (d) return d;
      }
      return a._index - b._index;
    })
    .map(function (s) {
      delete s._langCount;
      delete s._langs;
      delete s._height;
      delete s._index;
      return s;
    });
}

// ---- common/fireplayer.js ----
// FirePlayer/VPlayer hosts (ravok.buzz, play.zephyrix.org, ...): getVideo -> HLS master,
// then one multi-audio playlist per wanted resolution.

// "data": one data: URI playlist per resolution (1080p, 720p), each with every audio track.
// "master": the original master playlist (all resolutions, player picks quality).
var PER_RES_MODE = "data";
var WANTED_HEIGHTS = [1080, 720];
// Also emit one stream per audio language (only with PER_RES_MODE "data").
var PER_LANGUAGE = true;

function fpExtractEmbeds(html) {
  var re = /(https?:)?\/\/([a-z0-9.-]+)\/video\/([a-f0-9]{32})/gi;
  var seen = {};
  var out = [];
  var m;
  while ((m = re.exec(html))) {
    var host = m[2].toLowerCase();
    var key = host + "/" + m[3].toLowerCase();
    if (seen[key]) continue;
    seen[key] = true;
    out.push({ host: host, origin: "https://" + host, hash: m[3].toLowerCase() });
  }
  return out;
}

function fpHeaders(emb) {
  return { Referer: emb.origin + "/", Origin: emb.origin, "User-Agent": NAMA_UA };
}

function fpGetMasterUrl(emb, site) {
  return namaFetchJson(emb.origin + "/player/index.php?data=" + emb.hash + "&do=getVideo", {
    method: "POST",
    headers: {
      "Content-Type": "application/x-www-form-urlencoded",
      "X-Requested-With": "XMLHttpRequest",
      Referer: emb.origin + "/video/" + emb.hash,
      Origin: emb.origin,
    },
    body: "hash=" + emb.hash + "&r=" + encodeURIComponent(site.base + "/"),
  }).then(function (j) {
    var link = j.securedLink || j.videoSource;
    if (!link) throw new Error("getVideo: no source");
    return link;
  });
}

function fpAttr(line, name) {
  var m = new RegExp("[:,]" + name + '=("([^"]*)"|[^,]*)').exec(line);
  return m ? (m[2] !== undefined ? m[2] : m[1]) : "";
}

// Parses a master playlist; every URI is made absolute.
function fpParseMaster(text, masterUrl) {
  var lines = text.split(/\r?\n/);
  var res = { media: [], variants: [] };
  for (var i = 0; i < lines.length; i++) {
    var line = lines[i].trim();
    if (line.indexOf("#EXT-X-MEDIA:") === 0) {
      var uri = fpAttr(line, "URI");
      if (uri) line = line.replace('URI="' + uri + '"', 'URI="' + namaResolveUrl(uri, masterUrl) + '"');
      res.media.push({
        line: line,
        type: fpAttr(line, "TYPE"),
        lang: fpAttr(line, "LANGUAGE"),
        name: fpAttr(line, "NAME"),
      });
    } else if (line.indexOf("#EXT-X-STREAM-INF:") === 0) {
      var next = (lines[i + 1] || "").trim();
      var h = (/RESOLUTION=\d+x(\d+)/.exec(line) || [])[1];
      if (!h) h = (/NAME="(\d+)p"/.exec(line) || [])[1];
      res.variants.push({ inf: line, uri: namaResolveUrl(next, masterUrl), height: +h || 0 });
      i++;
    }
  }
  return res;
}

// onlyAudio: keep just that audio rendition (as the default) for a per-language stream.
function fpBuildPlaylist(parsed, variant, onlyAudio) {
  var out = ["#EXTM3U", "#EXT-X-VERSION:3"];
  parsed.media.forEach(function (m) {
    if (m.type === "SUBTITLES") out.push(m.line);
    else if (m.type === "AUDIO" && !onlyAudio) out.push(m.line);
    else if (m === onlyAudio) out.push(m.line.replace(/DEFAULT=NO/, "DEFAULT=YES"));
  });
  out.push(variant.inf, variant.uri);
  return out.join("\n") + "\n";
}

function fpStreams(emb, site, meta) {
  var headers = fpHeaders(emb);
  return fpGetMasterUrl(emb, site).then(function (masterUrl) {
    return namaFetchText(masterUrl, { headers: headers }).then(function (text) {
      var parsed = fpParseMaster(text, masterUrl);
      var audios = parsed.media.filter(function (m) {
        return m.type === "AUDIO";
      });
      var base = { site: site, meta: meta, host: emb.host, audios: audios, headers: headers };
      if (PER_RES_MODE === "master" || !parsed.variants.length) {
        var wanted = parsed.variants.filter(function (v) {
          return WANTED_HEIGHTS.indexOf(v.height) >= 0;
        });
        var heights = wanted.map(function (v) {
          return v.height;
        });
        var inf = (wanted[0] || parsed.variants[0] || {}).inf;
        return [namaFormatStream(base, masterUrl, heights.length ? heights : [0], inf)];
      }
      var streams = [];
      var heightsWanted = WANTED_HEIGHTS.filter(function (h) {
        return parsed.variants.some(function (x) {
          return x.height === h;
        });
      });
      // Older shows (e.g. Doraemon 1979) top out below 720p: offer the best there is.
      if (!heightsWanted.length) {
        heightsWanted = [
          Math.max.apply(
            null,
            parsed.variants.map(function (x) {
              return x.height;
            })
          ),
        ];
      }
      heightsWanted.forEach(function (h) {
        var v = parsed.variants.filter(function (x) {
          return x.height === h;
        })[0];
        if (!v) return;
        var url = "data:application/vnd.apple.mpegurl;base64," + namaBase64(fpBuildPlaylist(parsed, v));
        streams.push(namaFormatStream(base, url, [h], v.inf));
        if (!PER_LANGUAGE || audios.length < 2) return;
        audios.forEach(function (a) {
          var one = Object.assign({}, base, { audios: [a], perLanguage: true });
          var langUrl = "data:application/vnd.apple.mpegurl;base64," + namaBase64(fpBuildPlaylist(parsed, v, a));
          streams.push(namaFormatStream(one, langUrl, [h], v.inf));
        });
      });
      return streams;
    });
  });
}

// ---- common/toro.js ----
// Scraper for WordPress sites on the "torofilm" theme (animesalt.cx, watchanimeworld.one).

function toroNorm(s) {
  return String(s || "")
    .toLowerCase()
    .replace(/&#0?38;|&amp;/g, "and")
    .replace(/&#[0-9]+;|&[a-z]+;/g, " ")
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
}

function toroSearch(base, query) {
  return namaFetchText(base + "/?s=" + encodeURIComponent(query)).then(function (html) {
    var out = [];
    html.split("<article").slice(1).forEach(function (block) {
      var href = /href="([^"]+\/(series|movies)\/[^"]+)"/.exec(block);
      if (!href) return;
      var title = /class="entry-title"[^>]*>([^<]+)</.exec(block);
      var poster = /data-src="[^"]*image\.tmdb\.org\/t\/p\/\w+(\/[^"]+)"/.exec(block);
      out.push({
        url: href[1],
        type: href[2] === "movies" ? "movie" : "tv",
        title: title ? title[1].trim() : "",
        poster: poster ? poster[1] : "",
      });
    });
    return out;
  });
}

function toroScore(item, meta) {
  var score = 0;
  // Site titles may carry a year, e.g. "Doraemon (2005)".
  var siteYear = (/\((\d{4})\)\s*$/.exec(item.title) || [])[1];
  var t = toroNorm(item.title.replace(/\(\d{4}\)\s*$/, ""));
  var slug = toroNorm((/\/(?:series|movies)\/([^\/]+)/.exec(item.url) || [])[1]).replace(/ \d{4}$/, "");
  var tc = t.replace(/ /g, "");
  [meta.title, meta.original].concat(meta.altTitles || []).forEach(function (name) {
    var n = toroNorm(name);
    if (!n) return;
    var nc = n.replace(/ /g, "");
    if (t === n || slug === n || tc === nc) score = Math.max(score, 100);
    else if (t.indexOf(n) >= 0 || n.indexOf(t) >= 0 || (tc.length > 3 && nc.indexOf(tc) >= 0)) score = Math.max(score, 60);
    else {
      var words = n.split(" ");
      var hit = words.filter(function (w) {
        return (" " + t + " ").indexOf(" " + w + " ") >= 0;
      }).length;
      score = Math.max(score, Math.round((40 * hit) / words.length));
    }
  });
  if (meta.poster && item.poster === meta.poster) score += 80;
  if (siteYear && meta.year) score += siteYear === meta.year ? 40 : -40;
  if (item.type === meta.type) score += 20;
  else score -= 50;
  return score;
}

var TORO_MAX_ALT_QUERIES = 3;

function toroQueries(meta) {
  var qs = [meta.title, meta.original];
  if (meta.title && meta.title.indexOf(":") > 0) qs.push(meta.title.split(":")[0]);
  qs = qs.concat((meta.altTitles || []).slice(0, TORO_MAX_ALT_QUERIES));
  var seen = {};
  return qs.filter(function (q) {
    var k = toroNorm(q);
    if (!k || seen[k]) return false;
    seen[k] = true;
    return true;
  });
}

// Finds the best matching /series/ or /movies/ page for the TMDB meta.
function toroFindTitle(base, meta) {
  var queries = toroQueries(meta);
  var best = null;
  function next(i) {
    if (i >= queries.length || (best && best.score >= 100)) return Promise.resolve(best);
    return toroSearch(base, queries[i])
      .then(function (items) {
        items.forEach(function (it) {
          var s = toroScore(it, meta);
          if (s >= 50 && (!best || s > best.score)) best = { url: it.url, score: s };
        });
      })
      .catch(function () {})
      .then(function () {
        return next(i + 1);
      });
  }
  return next(0).then(function (b) {
    return b ? b.url : null;
  });
}

function toroEpisodeLinks(html) {
  var re = /href="(https?:\/\/[^"]+\/episode\/([^"\/]+)-(\d+)x(\d+)\/?)"/g;
  var out = [];
  var m;
  while ((m = re.exec(html))) out.push({ url: m[1], s: +m[3], e: +m[4] });
  return out;
}

function toroHasEmbed(html) {
  return /\/video\/[a-f0-9]{32}/i.test(html);
}

// Returns { url, html } of the episode page for TMDB season/episode.
function toroFindEpisode(base, seriesUrl, meta) {
  var slug = (/\/series\/([^\/]+)/.exec(seriesUrl) || [])[1];
  var direct = base + "/episode/" + slug + "-" + meta.season + "x" + meta.episode + "/";
  return namaFetchText(direct)
    .then(function (html) {
      if (toroHasEmbed(html)) return { url: direct, html: html };
      throw new Error("no embed");
    })
    .catch(function () {
      return toroAllEpisodes(base, seriesUrl).then(function (eps) {
        // Site seasons often differ from TMDB: episode numbers are usually absolute.
        var pick =
          eps.filter(function (x) {
            return x.e === meta.absEpisode;
          })[0] || eps[meta.absEpisode - 1];
        if (!pick) return null;
        return namaFetchText(pick.url).then(function (html) {
          return { url: pick.url, html: html };
        });
      });
    });
}

function toroAllEpisodes(base, seriesUrl) {
  return namaFetchText(seriesUrl).then(function (html) {
    var post = (/data-post="(\d+)"/.exec(html) || [])[1];
    var seasons = [];
    var re = /data-season="(\d+)"/g;
    var m;
    while ((m = re.exec(html))) if (seasons.indexOf(m[1]) < 0) seasons.push(m[1]);
    var all = toroEpisodeLinks(html);
    var jobs = post
      ? seasons.map(function (s) {
          return namaFetchText(base + "/wp-admin/admin-ajax.php", {
            method: "POST",
            headers: {
              "Content-Type": "application/x-www-form-urlencoded",
              "X-Requested-With": "XMLHttpRequest",
              Referer: seriesUrl,
            },
            body: "action=action_select_season&season=" + s + "&post=" + post,
          })
            .then(toroEpisodeLinks)
            .catch(function () {
              return [];
            });
        })
      : [];
    return Promise.all(jobs).then(function (lists) {
      lists.forEach(function (l) {
        all = all.concat(l);
      });
      var seen = {};
      return all
        .filter(function (x) {
          if (seen[x.url]) return false;
          seen[x.url] = true;
          return true;
        })
        .sort(function (a, b) {
          return a.s - b.s || a.e - b.e;
        });
    });
  });
}

// Entry point shared by every torofilm provider.
function toroGetStreams(site, tmdbId, mediaType, season, episode) {
  var meta;
  return tmdbMeta(tmdbId, mediaType, season, episode)
    .then(function (m) {
      meta = m;
      return toroFindTitle(site.base, meta);
    })
    .then(function (pageUrl) {
      if (!pageUrl) return null;
      if (meta.type === "movie") {
        return namaFetchText(pageUrl).then(function (html) {
          return { url: pageUrl, html: html };
        });
      }
      return toroFindEpisode(site.base, pageUrl, meta);
    })
    .then(function (page) {
      if (!page) return [];
      var embeds = fpExtractEmbeds(page.html);
      return Promise.all(
        embeds.map(function (emb) {
          return fpStreams(emb, site, meta).catch(function () {
            return [];
          });
        })
      ).then(function (lists) {
        return namaSortStreams([].concat.apply([], lists));
      });
    })
    .catch(function (e) {
      console.log("[" + site.name + "] " + (e && e.message));
      return [];
    });
}

// ---- multimovies/index.js ----
// MultiMovies (multimovies.wtf -> current mirror): every watch page lists third-party
// servers (watchConfig.initialServers). Each server gets an extractor below; HLS audio
// languages are merged into one multi-audio stream per resolution.
var SITE = { name: "MultiMovies", base: "https://m1.multimovies.courses" };
var MM_HOME = "https://multimovies.wtf/";
// Most audio languages merged into one stream (Indian, EN and JA are picked first).
var MM_MAX_AUDIO = 6;
// Audio playlists whose length differs from the base by more than this are another cut.
var MM_MAX_DRIFT = 3;
// Some mirror CDNs never answer: give up on a mirror, and on a whole server, after this.
var MM_MIRROR_TIMEOUT = 15000;
var MM_SERVER_TIMEOUT = 30000;
// Per playlist fetch: some proxy workers hang for over a minute.
var MM_FETCH_TIMEOUT = 8000;

var MM_LANG_ISO = {
  hindi: "hi", tamil: "ta", telugu: "te", malayalam: "ml", bengali: "bn", kannada: "kn",
  marathi: "mr", english: "en", japanese: "ja", korean: "ko", chinese: "zh", mandarin: "zh",
  french: "fr", spanish: "es", "latin american spanish": "es", russian: "ru", arabic: "ar",
  indonesian: "id", tagalog: "tl", filipino: "tl", portuguese: "pt", "brazilian portuguese": "pt",
  kurdish: "ku", german: "de", italian: "it", turkish: "tr", thai: "th", urdu: "ur",
  punjabi: "pa", gujarati: "gu", odia: "or", vietnamese: "vi", malay: "ms",
  // Filmu's short labels.
  esla: "es", ptbr: "pt",
};

function mmFetch(url, headers) {
  var h = Object.assign({ "User-Agent": NAMA_UA }, headers || {});
  return fetch(url, { headers: h }).then(function (res) {
    if (!res.ok) throw new Error("HTTP " + res.status + " " + url);
    return res.text().then(function (text) {
      return { url: res.url || url, text: text };
    });
  });
}

function mmTimeout(promise, ms) {
  return Promise.race([
    promise,
    new Promise(function (_, reject) {
      setTimeout(function () {
        reject(new Error("timeout"));
      }, ms);
    }),
  ]);
}

// Playlist fetch with a timeout and one retry (proxy workers drop requests under load).
function mmFetchPlaylist(url, headers) {
  function once() {
    return mmTimeout(namaFetchText(url, { headers: headers }), MM_FETCH_TIMEOUT);
  }
  return once().catch(once);
}

// Balanced-brace JSON value that starts right after `marker`.
function mmJsonAfter(text, marker) {
  var i = text.indexOf(marker);
  if (i < 0) return null;
  i += marker.length;
  while (text.charAt(i) === " ") i++;
  var open = text.charAt(i);
  var close = open === "[" ? "]" : "}";
  var depth = 0;
  var inStr = false;
  for (var j = i; j < text.length; j++) {
    var c = text.charAt(j);
    if (inStr) {
      if (c === "\\") j++;
      else if (c === '"') inStr = false;
    } else if (c === '"') inStr = true;
    else if (c === open) depth++;
    else if (c === close && --depth === 0) return JSON.parse(text.slice(i, j + 1));
  }
  return null;
}

// ---- byte helpers (Hermes has no atob/TextDecoder) ----

function mmB64Bytes(s) {
  s = s.replace(/-/g, "+").replace(/_/g, "/").replace(/[^A-Za-z0-9+\/]/g, "");
  var out = [];
  var buf = 0;
  var bits = 0;
  for (var i = 0; i < s.length; i++) {
    buf = (buf << 6) | NAMA_B64.indexOf(s.charAt(i));
    bits += 6;
    if (bits >= 8) {
      bits -= 8;
      out.push((buf >> bits) & 255);
    }
  }
  return out;
}

function mmUtf8(bytes) {
  var s = "";
  for (var i = 0; i < bytes.length; i++) {
    var b = bytes[i];
    if (b < 0x80) s += String.fromCharCode(b);
    else if (b < 0xe0) s += String.fromCharCode(((b & 31) << 6) | (bytes[++i] & 63));
    else if (b < 0xf0) s += String.fromCharCode(((b & 15) << 12) | ((bytes[++i] & 63) << 6) | (bytes[++i] & 63));
    else {
      var cp = ((b & 7) << 18) | ((bytes[++i] & 63) << 12) | ((bytes[++i] & 63) << 6) | (bytes[++i] & 63);
      cp -= 0x10000;
      s += String.fromCharCode(0xd800 + (cp >> 10), 0xdc00 + (cp & 1023));
    }
  }
  return s;
}

function mmSha256Hex(ascii) {
  var K = [];
  var H = [];
  var n = 2;
  var found = 0;
  function frac(x) {
    return ((x - Math.floor(x)) * 4294967296) | 0;
  }
  while (found < 64) {
    var prime = true;
    for (var d = 2; d * d <= n; d++) if (n % d === 0) prime = false;
    if (prime) {
      if (found < 8) H[found] = frac(Math.pow(n, 1 / 2));
      K[found++] = frac(Math.pow(n, 1 / 3));
    }
    n++;
  }
  var bytes = [];
  for (var i = 0; i < ascii.length; i++) bytes.push(ascii.charCodeAt(i) & 255);
  var bitLen = bytes.length * 8;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);
  for (var s = 7; s >= 0; s--) bytes.push(s > 3 ? 0 : (bitLen >>> (s * 8)) & 255);
  function rot(x, r) {
    return (x >>> r) | (x << (32 - r));
  }
  for (var off = 0; off < bytes.length; off += 64) {
    var w = [];
    for (var t = 0; t < 64; t++) {
      if (t < 16) {
        var p = off + t * 4;
        w[t] = (bytes[p] << 24) | (bytes[p + 1] << 16) | (bytes[p + 2] << 8) | bytes[p + 3];
      } else {
        var s0 = rot(w[t - 15], 7) ^ rot(w[t - 15], 18) ^ (w[t - 15] >>> 3);
        var s1 = rot(w[t - 2], 17) ^ rot(w[t - 2], 19) ^ (w[t - 2] >>> 10);
        w[t] = (w[t - 16] + s0 + w[t - 7] + s1) | 0;
      }
    }
    var a = H[0], b = H[1], c = H[2], dd = H[3], e = H[4], f = H[5], g = H[6], h = H[7];
    for (var r = 0; r < 64; r++) {
      var t1 = (h + (rot(e, 6) ^ rot(e, 11) ^ rot(e, 25)) + ((e & f) ^ (~e & g)) + K[r] + w[r]) | 0;
      var t2 = ((rot(a, 2) ^ rot(a, 13) ^ rot(a, 22)) + ((a & b) ^ (a & c) ^ (b & c))) | 0;
      h = g; g = f; f = e; e = (dd + t1) | 0; dd = c; c = b; b = a; a = (t1 + t2) | 0;
    }
    H = [(H[0] + a) | 0, (H[1] + b) | 0, (H[2] + c) | 0, (H[3] + dd) | 0, (H[4] + e) | 0, (H[5] + f) | 0, (H[6] + g) | 0, (H[7] + h) | 0];
  }
  return H.map(function (x) {
    return ("00000000" + (x >>> 0).toString(16)).slice(-8);
  }).join("");
}

// ---- HLS: multi-audio playlists ----

function mmLangOf(label, meta) {
  var l = String(label || "").toLowerCase().trim();
  // MovieBox "<language> sub" sources carry the original audio.
  if (/\bsub(s|titles?)?$/.test(l) || l === "original" || /orion · original/.test(l)) return meta.originalLanguage || "";
  l = l.replace(/^.*·\s*/, "").replace(/\s*\(.*\)$/, "");
  return MM_LANG_ISO[l] || "";
}

function mmLangName(iso) {
  for (var k in MM_LANG_ISO) if (MM_LANG_ISO[k] === iso) return k.charAt(0).toUpperCase() + k.slice(1);
  return iso.toUpperCase();
}

function mmLangRank(iso) {
  var i = NAMA_LANG_ORDER.indexOf(String(iso).toUpperCase());
  return i < 0 ? 99 : i;
}

function mmPlaylistSeconds(url, headers) {
  return mmFetchPlaylist(url, headers).then(function (t) {
    var sum = 0;
    var re = /#EXTINF:([0-9.]+)/g;
    var m;
    while ((m = re.exec(t))) sum += parseFloat(m[1]);
    return sum;
  });
}

// One stream per wanted resolution, each carrying every audio rendition of `parsed`.
function mmStreamsFromParsed(parsed, ctx) {
  var heights = WANTED_HEIGHTS.filter(function (h) {
    return parsed.variants.some(function (v) {
      return v.height === h;
    });
  });
  if (!heights.length && parsed.variants.length) {
    heights = [Math.max.apply(null, parsed.variants.map(function (v) {
      return v.height;
    }))];
  }
  var audios = parsed.media.filter(function (m) {
    return m.type === "AUDIO";
  });
  var base = Object.assign({}, ctx, { audios: audios.length ? audios : ctx.fallbackAudio || [] });
  return heights.map(function (h) {
    var v = parsed.variants.filter(function (x) {
      return x.height === h;
    })[0];
    var url = "data:application/vnd.apple.mpegurl;base64," + namaBase64(fpBuildPlaylist(parsed, v));
    return namaFormatStream(base, url, [h], v.inf);
  });
}

// sources: [{ url, label }] HLS masters of the same title, one audio language each (or a
// master that already has several). Returns multi-audio streams for the best video.
function mmHlsStreams(sources, ctx) {
  var headers = ctx.headers;
  return Promise.all(
    sources.map(function (s) {
      return mmFetchPlaylist(s.url, headers)
        .then(function (text) {
          var parsed = fpParseMaster(text, s.url);
          var iso = mmLangOf(s.label, ctx.meta);
          // Unlabelled renditions ("Audio") take the source's language.
          parsed.media.forEach(function (m) {
            if (m.type === "AUDIO" && !m.lang && iso) m.lang = iso;
          });
          return { src: s, parsed: parsed, iso: iso };
        })
        .catch(function () {
          return null;
        });
    })
  ).then(function (list) {
    list = list.filter(function (x) {
      return x && x.parsed.variants.length;
    });
    if (!list.length) return [];
    if (list.length === 1) {
      var only = list[0];
      if (!only.parsed.media.some(function (m) {
        return m.type === "AUDIO";
      }) && only.iso) {
        ctx = Object.assign({}, ctx, { fallbackAudio: [{ lang: only.iso, name: mmLangName(only.iso) }] });
      }
      return mmStreamsFromParsed(only.parsed, ctx);
    }
    return mmMergeAudio(list, ctx);
  });
}

function mmMergeAudio(list, ctx) {
  // Separate audio renditions only; muxed sources can't be merged.
  var cands = [];
  var seen = {};
  list
    .slice()
    .sort(function (a, b) {
      return mmLangRank(a.iso) - mmLangRank(b.iso);
    })
    .forEach(function (x) {
      var a = x.parsed.media.filter(function (m) {
        return m.type === "AUDIO" && fpAttr(m.line, "URI");
      })[0];
      var iso = x.iso || (a && a.lang) || "";
      if (!a || !x.parsed.variants[0].inf.match(/AUDIO="/) || seen[iso || x.src.url]) return;
      seen[iso || x.src.url] = true;
      cands.push({ x: x, iso: iso, uri: fpAttr(a.line, "URI"), channels: fpAttr(a.line, "CHANNELS"), name: x.iso ? mmLangName(x.iso) : x.src.label || a.name || "Audio" });
    });
  if (!cands.length) return mmStreamsFromParsed(list[0].parsed, ctx);
  cands = cands.slice(0, MM_MAX_AUDIO + 2);
  return Promise.all(
    cands.map(function (c) {
      return mmPlaylistSeconds(c.uri, ctx.headers).catch(function () {
        return -1;
      });
    })
  ).then(function (secs) {
    // The base is the first language whose audio loaded.
    var baseSec = secs.filter(function (x) {
      return x > 0;
    })[0];
    var keep = cands
      .filter(function (c, i) {
        return secs[i] > 0 && Math.abs(secs[i] - baseSec) <= MM_MAX_DRIFT;
      })
      .slice(0, MM_MAX_AUDIO);
    if (!keep.length) return [];
    var base = keep[0].x.parsed;
    var media = base.media.filter(function (m) {
      return m.type === "SUBTITLES";
    });
    keep.forEach(function (c, i) {
      var line =
        '#EXT-X-MEDIA:TYPE=AUDIO,GROUP-ID="mmaud",NAME="' + c.name + '",LANGUAGE="' + (c.iso || "und") +
        '",DEFAULT=' + (i ? "NO" : "YES") + ',AUTOSELECT=YES' +
        (c.channels ? ',CHANNELS="' + c.channels + '"' : "") + ',URI="' + c.uri + '"';
      media.push({ line: line, type: "AUDIO", lang: c.iso, name: c.name });
    });
    var variants = base.variants.map(function (v) {
      return Object.assign({}, v, { inf: v.inf.replace(/AUDIO="[^"]*"/, 'AUDIO="mmaud"') });
    });
    return mmStreamsFromParsed({ media: media, variants: variants }, ctx);
  });
}

function mmMp4Stream(url, label, height, ctx) {
  var iso = mmLangOf(label, ctx.meta);
  var c = Object.assign({}, ctx, { audios: iso ? [{ lang: iso, name: mmLangName(iso) }] : [], format: "MP4" });
  return namaFormatStream(c, url, [height || 0]);
}

function mmQualityHeight(q) {
  return +((/(\d{3,4})p/.exec(q || "") || [])[1] || 0);
}

// Sources with a known language first, original-language "sub" duplicates dropped.
function mmPickSources(list, meta) {
  var seen = {};
  return list
    .map(function (s) {
      return Object.assign({}, s, { iso: mmLangOf(s.label, meta) });
    })
    .filter(function (s) {
      var k = s.iso || "?" + s.label;
      if (seen[k]) return false;
      seen[k] = true;
      return true;
    })
    .sort(function (a, b) {
      return mmLangRank(a.iso) - mmLangRank(b.iso);
    });
}

// ---- packed JWPlayer hosts (StreamHG, EarnVids/FileLions) ----

function mmUnpack(html) {
  var m = /eval\(function\(p,a,c,k,e,d\)\{[\s\S]*?\}\('([\s\S]*?)',(\d+),(\d+),'([\s\S]*?)'\.split\('\|'\)/.exec(html);
  if (!m) return "";
  var p = m[1];
  var a = +m[2];
  var c = +m[3];
  var k = m[4].split("|");
  function enc(n) {
    return (n < a ? "" : enc(Math.floor(n / a))) + ((n = n % a) > 35 ? String.fromCharCode(n + 29) : n.toString(36));
  }
  while (c--) if (k[c]) p = p.replace(new RegExp("\\b" + enc(c) + "\\b", "g"), k[c]);
  return p;
}

function mmPackedStreams(embedUrl, referer, ctx) {
  return mmFetch(embedUrl, { Referer: referer }).then(function (page) {
    var js = mmUnpack(page.text);
    var links = {};
    var lm = /links\s*=\s*(\{[^}]*\})/.exec(js);
    if (lm) links = JSON.parse(lm[1]);
    // hls4 is served by the embed host itself; the hls2 CDN sometimes never answers.
    var file = links.hls4 || links.hls2 || links.hls3 || (/file\s*:\s*"([^"]+\.(?:m3u8|txt)[^"]*)"/.exec(js) || [])[1];
    if (!file) throw new Error("packed: no source");
    var origin = namaOrigin(page.url);
    var headers = { Referer: origin + "/", Origin: origin, "User-Agent": NAMA_UA };
    var c = Object.assign({}, ctx, { headers: headers, host: namaHost(page.url) });
    return mmHlsStreams([{ url: namaResolveUrl(file, page.url), label: "" }], c);
  });
}

function mmFirstOk(tasks) {
  var i = 0;
  function next() {
    if (i >= tasks.length) return Promise.resolve([]);
    return mmTimeout(tasks[i++](), MM_MIRROR_TIMEOUT)
      .catch(function () {
        return [];
      })
      .then(function (s) {
        return s.length ? s : next();
      });
  }
  return next();
}

// ---- extractors, one per server host ----

function mmVidrift(srv, ctx) {
  var origin = namaOrigin(srv.url);
  var headers = { Referer: origin + "/", Origin: origin, "User-Agent": NAMA_UA };
  var c = Object.assign({}, ctx, { headers: headers, host: namaHost(srv.url) });
  return mmFetch(srv.url, { Referer: SITE.base + "/" }).then(function (page) {
    var em = mmJsonAfter(page.text, "var embedMeta =") || {};
    var orion = em.orionStreams;
    if (orion && orion.length) return mmVidriftStreams(orion, origin, c);
    var path = /\/embed\/(movie\/\d+|tv\/\d+\/\d+\/\d+)/.exec(srv.url)[1];
    var providers = ["orion", "animedub", "anime", "vela"];
    return mmFirstOk(
      providers.map(function (p) {
        return function () {
          var q = "?token=" + encodeURIComponent(em.playbackToken || "") + "&provider=" + p + "&parent=" + encodeURIComponent(em.parent || "");
          return namaFetchJson(origin + "/api/source/" + path + q, { headers: { Referer: srv.url } }).then(function (d) {
            return mmVidriftStreams(d.streams || [], origin, c);
          });
        };
      })
    );
  });
}

function mmVidriftStreams(list, origin, ctx) {
  var hls = [];
  var mp4 = [];
  list.forEach(function (s) {
    var u = s.url || s.proxyUrl;
    if (!u) return;
    var item = { url: namaResolveUrl(u, origin + "/"), label: s.name || "" };
    (s.type === "mp4" ? mp4 : hls).push(item);
  });
  return mmHlsStreams(mmPickSources(hls, ctx.meta), ctx).then(function (streams) {
    if (streams.length) return streams;
    return mmPickSources(mp4, ctx.meta).slice(0, 1).map(function (s) {
      return mmMp4Stream(s.url, s.label, 0, ctx);
    });
  });
}

function mmVidbolt(srv, ctx) {
  var origin = namaOrigin(srv.url);
  var m = /\/(movie|tv)\/(\d+)(?:\/(\d+)\/(\d+))?/.exec(srv.url);
  var q = m[1] === "movie" ? "type=movie&id=" + m[2] : "type=tv&id=" + m[2] + "&season=" + m[3] + "&episode=" + m[4];
  var headers = { Referer: origin + "/", Origin: origin, "User-Agent": NAMA_UA };
  var c = Object.assign({}, ctx, { headers: headers, host: namaHost(srv.url) });
  return namaFetchJson(origin + "/api/resolve?" + q, { headers: { Referer: srv.url } }).then(function (j) {
    var sources = ((j.stream && j.stream.sources) || []).filter(function (s) {
      return s.kind === "hls";
    });
    return mmHlsStreams(
      mmPickSources(
        sources.map(function (s) {
          return { url: s.url, label: s.language };
        }),
        ctx.meta
      ),
      c
    );
  });
}

// Filmu (embed.filmu.in -> vidly.pro): the stream list ships "sealed" in the RSC payload.
var MM_FILMU_KEY = "vY7#qL2!mZ9@wK4$";

function mmFilmuUnseal(sealed) {
  var all = mmB64Bytes(sealed.slice(3));
  var nonce = all.slice(0, 12);
  var data = all.slice(12);
  var st = [];
  for (var s = 0; s < 4; s++) {
    var n = (0x811c9dc5 ^ (0x9e3779b9 * s)) >>> 0;
    for (var i = 0; i < MM_FILMU_KEY.length; i++) n = Math.imul(n ^ MM_FILMU_KEY.charCodeAt(i), 0x1000193) >>> 0;
    for (var j = 0; j < nonce.length; j++) n = Math.imul(n ^ nonce[j], 0x1000193) >>> 0;
    st.push(n);
  }
  var a = st[0], b = st[1], c = st[2], d = st[3], r = 0;
  for (var t = 0; t < data.length; t++) {
    if ((t & 3) === 0) {
      c >>>= 0;
      d >>>= 0;
      var e = ((a >>>= 0) + (b >>>= 0)) | 0;
      a = b ^ (b >>> 9);
      b = (c + (c << 3)) | 0;
      c = ((c << 21) | (c >>> 11));
      d = (d + 1) | 0;
      e = (e + d) | 0;
      c = (c + e) | 0;
      r = e >>> 0;
    }
    data[t] ^= (r >>> ((t & 3) * 8)) & 255;
  }
  return JSON.parse(mmUtf8(data));
}

function mmFilmu(srv, ctx) {
  return mmFetch(srv.url, { Referer: SITE.base + "/" }).then(function (page) {
    var rsc = "";
    var re = /self\.__next_f\.push\(\[1,"((?:[^"\\]|\\.)*)"\]\)/g;
    var m;
    while ((m = re.exec(page.text))) rsc += JSON.parse('"' + m[1] + '"');
    var ref = /"sealed":"\$([0-9a-f]+)"/.exec(rsc);
    var sealed;
    if (ref) {
      var row = new RegExp("(?:^|\\n)" + ref[1] + ":T([0-9a-f]+),").exec(rsc);
      if (row) sealed = rsc.substr(row.index + row[0].length, parseInt(row[1], 16));
    } else sealed = (/"sealed":"(v1\.[A-Za-z0-9_-]+)"/.exec(rsc) || [])[1];
    if (!sealed) throw new Error("filmu: no sealed payload");
    var data = mmFilmuUnseal(sealed);
    var origin = namaOrigin(page.url);
    var headers = { Referer: origin + "/", Origin: origin, "User-Agent": NAMA_UA };
    var c = Object.assign({}, ctx, { headers: headers, host: namaHost(page.url) });
    var hls = (data.streams || []).filter(function (s) {
      return s.type === "hls";
    });
    return mmHlsStreams(
      mmPickSources(
        hls.map(function (s) {
          return { url: s.url, label: s.language };
        }),
        ctx.meta
      ),
      c
    );
  });
}

// Nexus (moviesnexus.fun): server action token + sha256 proof of work -> /api/extract.
var MM_NEXUS_ACTION = "6083fa9bf317439b0ab1f882f7ba7ccd49d1369361";
var MM_NEXUS_KEY = "nexus-super-secret-key-999";

function mmNexusDecode(s) {
  if (!/^[0-9a-f]+$/i.test(s || "")) return s;
  var out = "";
  for (var i = 0; i < s.length; i += 2) {
    out += String.fromCharCode(parseInt(s.substr(i, 2), 16) ^ MM_NEXUS_KEY.charCodeAt((i / 2) % MM_NEXUS_KEY.length));
  }
  return out;
}

function mmNexus(srv, ctx) {
  var origin = namaOrigin(srv.url);
  var m = /\/(movie|tv)\/(\d+)(?:\/(\d+)\/(\d+))?/.exec(srv.url);
  var isTv = m[1] === "tv";
  var page = origin + "/" + (isTv ? "tv/" + m[2] + "/" + m[3] + "/" + m[4] : "movie/" + m[2]);
  var key = isTv ? m[2] + "-s" + m[3] + "e" + m[4] : m[2];
  return namaFetchText(page, {
    method: "POST",
    headers: { "Next-Action": MM_NEXUS_ACTION, Accept: "text/x-component", "Content-Type": "text/plain;charset=UTF-8", Referer: page },
    body: JSON.stringify([key, m[1]]),
  })
    .then(function (t) {
      var tok = JSON.parse((/(?:^|\n)1:(\{.*\})/.exec(t) || [])[1]);
      var answer = "";
      if (tok.challengeSeed) {
        for (var n = 0; n < 200000; n++) {
          if (mmSha256Hex(tok.challengeSeed + ":" + n).indexOf(tok.difficulty || "000") === 0) break;
        }
        answer = String(n);
      }
      var q =
        "mediaType=" + m[1] + "&tmdbId=" + m[2] + (isTv ? "&season=" + m[3] + "&episode=" + m[4] : "") +
        "&token=" + tok.token + "&nonce=" + tok.nonce + "&timestamp=" + tok.timestamp +
        (answer ? "&challengeSeed=" + encodeURIComponent(tok.challengeSeed) + "&challengeAnswer=" + answer : "");
      return namaFetchJson(origin + "/api/extract?" + q, { headers: { Referer: page } });
    })
    .then(function (d) {
      var servers = (d.servers || []).filter(function (s) {
        return s.type === "m3u8" || (s.audioTracks || []).length;
      });
      // Multi-audio servers first.
      servers.sort(function (a, b) {
        return (b.audioTracks || []).length - (a.audioTracks || []).length;
      });
      return Promise.all(
        servers.slice(0, 3).map(function (s) {
          var headers = Object.assign({ "User-Agent": NAMA_UA }, s.headers || {});
          var c = Object.assign({}, ctx, { headers: headers, host: namaHost(origin) });
          var tracks = (s.audioTracks || []).map(function (a) {
            return { url: mmNexusDecode(a.url), label: a.label };
          });
          var list = tracks.length ? mmPickSources(tracks, ctx.meta) : [{ url: mmNexusDecode(s.url), label: "" }];
          return mmHlsStreams(list, c).catch(function () {
            return [];
          });
        })
      ).then(mmBestPerHeight);
    });
}

// VIDOUT (vidout.pages.dev): stream links come from a GitHub-hosted catalogue.
var MM_VIDOUT_DB = "https://raw.githubusercontent.com/Watchout2025/api/refs/heads/main/hls/";

function mmVidout(srv, ctx) {
  var m = /\/(movie|tv)\/(\d+)(?:\/s(\d+)\/e(\d+))?/i.exec(srv.url);
  var tmdb = m && /^\d+$/.test(m[2]) ? m[2] : ctx.meta.tmdbId;
  var isTv = ctx.meta.type === "tv";
  var lookup = isTv
    ? namaFetchJson(MM_VIDOUT_DB + "tv/" + tmdb + "/S" + ctx.meta.season + ".json").then(function (j) {
        return j[String(ctx.meta.episode)] || "";
      })
    : namaFetchText(MM_VIDOUT_DB + "movie/" + tmdb);
  // Titles missing from the catalogue (404) have no VIDOUT stream.
  lookup = lookup.catch(function () {
    return "";
  });
  return lookup.then(function (link) {
    link = String(link || "").trim();
    if (!/^https?:\/\//.test(link) || link.indexOf("#") >= 0) return [];
    if (/\/(e|v|embed)\/[a-z0-9]+$/i.test(link)) return mmPackedStreams(link, "https://vidout.pages.dev/", ctx);
    var origin = "https://vidout.pages.dev";
    var c = Object.assign({}, ctx, { headers: { Referer: origin + "/", Origin: origin, "User-Agent": NAMA_UA }, host: namaHost(link) });
    return mmHlsStreams([{ url: link, label: "" }], c);
  });
}

// Some hosts (StreamHG / EarnVids mirrors on TikTok's image CDN) disguise TS segments as PNGs:
// a tiny image header, then the video. Web players strip it; app players fail, so such
// streams are dropped. Checks the first 16 bytes of the first video segment.
function mmDisguised(stream) {
  if (!/^data:/.test(stream.url || "")) return Promise.resolve(false);
  var lines = mmUtf8(mmB64Bytes(stream.url.split("base64,")[1] || "")).split("\n");
  var i = lines.findIndex(function (l) {
    return l.indexOf("#EXT-X-STREAM-INF") === 0;
  });
  var variant = i >= 0 ? (lines[i + 1] || "").trim() : "";
  if (!variant) return Promise.resolve(false);
  return namaFetchText(variant, { headers: stream.headers })
    .then(function (text) {
      var seg = text.split(/\r?\n/).filter(function (l) {
        return l && l.charAt(0) !== "#";
      })[0];
      if (!seg) return false;
      return fetch(namaResolveUrl(seg.trim(), variant), {
        headers: Object.assign({ Range: "bytes=0-15" }, stream.headers),
      })
        .then(function (r) {
          return r.arrayBuffer();
        })
        .then(function (buf) {
          var b = new Uint8Array(buf);
          var png = b[0] === 0x89 && b[1] === 0x50 && b[2] === 0x4e && b[3] === 0x47;
          var jpg = b[0] === 0xff && b[1] === 0xd8;
          var gif = b[0] === 0x47 && b[1] === 0x49 && b[2] === 0x46;
          return png || jpg || gif;
        });
    })
    .catch(function () {
      return false;
    });
}

var MM_EXTRACTORS = [
  { test: /vidrift\./, run: mmVidrift },
  { test: /vidbolt\./, run: mmVidbolt },
  { test: /filmu\.|vidly\./, run: mmFilmu },
  { test: /moviesnexus\./, run: mmNexus },
  { test: /vidout\./, run: mmVidout },
];

// Keeps the stream with the most audio languages for each resolution; other
// resolutions only when none of WANTED_HEIGHTS is there.
function mmBestPerHeight(lists) {
  var best = {};
  var all = [].concat.apply([], lists);
  var wanted = all.filter(function (s) {
    return WANTED_HEIGHTS.indexOf(s._height) >= 0;
  });
  (wanted.length ? wanted : all).forEach(function (s) {
    var k = s._height;
    if (!best[k] || s._langCount > best[k]._langCount) best[k] = s;
  });
  return Object.keys(best).map(function (k) {
    return best[k];
  });
}

// ---- site ----

function mmBase() {
  return namaFetchText(MM_HOME)
    .then(function (html) {
      var m = /<a[^>]+href="(https?:\/\/[^"]+)"[^>]*class="cta-primary"/.exec(html) || /class="cta-primary"[^>]*href="(https?:\/\/[^"]+)"/.exec(html);
      return m ? m[1].replace(/\/+$/, "") : SITE.base;
    })
    .catch(function () {
      return SITE.base;
    });
}

function mmSearch(base, query) {
  // The search is literal: "Your Name." and "Dead-End Job" find nothing,
  // "Your Name" and "Dead End Job" do.
  query = query.replace(/[^\w\s'&]+/g, " ").replace(/\s+/g, " ").trim();
  return namaFetchJson(base + "/api/search?q=" + encodeURIComponent(query) + "&limit=20").then(function (d) {
    var list = (d.movies || []).concat(d.tv_shows || []);
    if (!list.length && Array.isArray(d.results)) list = d.results;
    return list.map(function (x) {
      var isMovie = x.type === "movie";
      return {
        url: base + x.url,
        type: isMovie ? "movie" : "tv",
        // toroScore reads a trailing "(year)"; the site's tv years are often the dub's year.
        title: x.title + (isMovie && x.year ? " (" + x.year + ")" : ""),
        poster: (/\/t\/p\/\w+(\/[^"?]+)/.exec(x.poster || "") || [])[1] || "",
      };
    });
  });
}

// Candidate title pages, best match first.
function mmCandidates(base, meta) {
  var found = {};
  return Promise.all(
    toroQueries(meta).map(function (q) {
      return mmSearch(base, q).catch(function () {
        return [];
      });
    })
  ).then(function (lists) {
    [].concat.apply([], lists).forEach(function (it) {
      var s = toroScore(it, meta);
      if (s >= 50 && (!found[it.url] || s > found[it.url].score)) found[it.url] = { url: it.url, score: s };
    });
    return Object.keys(found)
      .map(function (k) {
        return found[k];
      })
      .sort(function (a, b) {
        return b.score - a.score;
      });
  });
}

// Every server but the site's own mirrors takes TMDB ids, so when the title page can't be
// found the list is built here (same URLs the site uses).
function mmDirectServers(meta) {
  var id = meta.tmdbId;
  var s = meta.season;
  var e = meta.episode;
  if (meta.type === "movie") {
    return [
      { name: "Nexus", url: "https://www.moviesnexus.fun/movie/" + id + "?sv=multi-audio" },
      { name: "Vidrift", url: "https://embed.vidrift.net/embed/movie/" + id },
      { name: "VIDOUT", url: "https://vidout.pages.dev/movie/" + id },
      { name: "Filmu", url: "https://embed.filmu.in/movie/" + id },
      { name: "VidBolt", url: "https://vidbolt.xyz/movie/" + id },
    ];
  }
  return [
    { name: "Nexus", url: "https://www.moviesnexus.fun/tv/" + id + "/" + s + "/" + e },
    { name: "Vidrift", url: "https://embed.vidrift.net/embed/tv/" + id + "/" + s + "/" + e },
    { name: "VIDOUT", url: "https://vidout.pages.dev/tv/" + id + "/s" + s + "/e" + e },
    { name: "Filmu", url: "https://embed.filmu.in/tv/" + id + "/" + s + "/" + e },
    { name: "VidBolt", url: "https://vidbolt.xyz/tv/" + id + "/" + s + "/" + e },
  ];
}

function mmWatchServers(pageUrl) {
  return namaFetchText(pageUrl).then(function (html) {
    var cfg = mmJsonAfter(html, "const watchConfig =");
    return (cfg && cfg.initialServers) || [];
  });
}

// The page is right when its server links carry the TMDB id.
function mmServersMatch(servers, meta) {
  var re = new RegExp("[/=]" + meta.tmdbId + "(?:[/?&]|$)");
  return servers.some(function (s) {
    return re.test(s.url || "");
  });
}

// Seasons on the site can differ from TMDB (Naruto: TMDB 1x220, site 4x52 with absolute
// episode numbers), so after the TMDB S/E page, try the site season holding absEpisode.
function mmEpisodeUrls(seriesUrl, meta) {
  var direct = seriesUrl + "/season/" + meta.season + "/episode/" + meta.episode;
  return namaFetchText(seriesUrl)
    .then(function (html) {
      var urls = [direct];
      var before = 0;
      var re = /<option value="(\d+)"[^>]*>\s*Season \d+\s*·\s*(\d+) episodes/g;
      var m;
      while ((m = re.exec(html))) {
        var count = +m[2];
        if (meta.absEpisode > before && meta.absEpisode <= before + count) {
          urls.push(seriesUrl + "/season/" + m[1] + "/episode/" + meta.absEpisode);
          urls.push(seriesUrl + "/season/" + m[1] + "/episode/" + (meta.absEpisode - before));
        }
        before += count;
      }
      return urls.filter(function (u, i) {
        return urls.indexOf(u) === i;
      });
    })
    .catch(function () {
      return [direct];
    });
}

function mmFindServers(base, meta) {
  return mmCandidates(base, meta).then(function (cands) {
    var urls = [];
    var ci = 0;
    function next() {
      if (urls.length) {
        return mmWatchServers(urls.shift())
          .then(function (servers) {
            return servers.length && mmServersMatch(servers, meta) ? servers : next();
          })
          .catch(next);
      }
      if (ci >= Math.min(cands.length, 3)) return [];
      var c = cands[ci++];
      if (meta.type === "movie") urls = [c.url];
      else
        return mmEpisodeUrls(c.url, meta).then(function (list) {
          urls = list;
          return next();
        });
      return next();
    }
    return next();
  });
}

function getStreams(tmdbId, mediaType, season, episode) {
  var meta;
  return tmdbMeta(tmdbId, mediaType, season, episode)
    .then(function (m) {
      meta = m;
      return mmBase();
    })
    .then(function (base) {
      SITE.base = base;
      return mmFindServers(base, meta);
    })
    .then(function (servers) {
      return servers.length ? servers : mmDirectServers(meta);
    })
    .then(function (servers) {
      return Promise.all(
        servers.map(function (srv) {
          var ex = MM_EXTRACTORS.filter(function (x) {
            return x.test.test(srv.url || "");
          })[0];
          if (!ex) return [];
          var ctx = { site: SITE, server: srv.name, meta: meta, host: namaHost(srv.url), audios: [] };
          return mmTimeout(ex.run(srv, ctx), MM_SERVER_TIMEOUT)
            .then(function (streams) {
              streams = mmBestPerHeight([streams]);
              if (!streams.length) return streams;
              return mmDisguised(streams[0]).then(function (bad) {
                if (bad) console.log("[MultiMovies] " + srv.name + ": segments disguised as images, skipped");
                return bad ? [] : streams;
              });
            })
            .catch(function (e) {
              console.log("[MultiMovies] " + srv.name + ": " + (e && e.message));
              return [];
            });
        })
      );
    })
    .then(function (lists) {
      return namaSortStreams([].concat.apply([], lists));
    })
    .catch(function (e) {
      console.log("[MultiMovies] " + (e && e.message));
      return [];
    });
}

if (typeof module !== "undefined" && module.exports) {
  module.exports = { getStreams: getStreams };
} else {
  global.getStreams = getStreams;
}
